import { type AppUser } from "@/features/auth/hooks/useAuth"
import { type Client } from "@/features/crm/hooks/CRM_hook/use_client"

import { type Payment } from "../../hooks/CRM_hook/use_devis"
import { type QuoteProduct } from "./creation"

export const NokkProjectLogo =
    "data:image/png;base64,"
export const VintageLogo =
    "data:image/png;base64,"

export const DarkVintage =
    "data:image/png;base64,"

export type PropsGenerateDevisPDF = {
    numeroDevis: string
    client: Client
    clientSiret?: string
    clientTva?: string
    expirationDate: string
    products: QuoteProduct[]
    remise: QuoteProduct[] | null
    payments: Payment[] | null

    // Nouveaux champs obligatoires pour garantir l'exactitude
    totalHT: number
    totalTVA: number
    totalTTC: number

    poid_balance?: number // <-- AJOUTE CECI
    round2: (num: number) => number
    user: AppUser | null
    logo: boolean
    condition: string
    Livraison: string
    note: string
    urgence?: "normale" | "haute" | "élevée" | null
}

export const generateDevisPDF = async (
    props: PropsGenerateDevisPDF,
    returnBase64 = false
): Promise<string | undefined> => {
    const {
        numeroDevis,
        client,
        clientSiret,
        clientTva,
        expirationDate,
        products,
        round2,
        logo,
        Livraison,
        remise,
        user,
        note,
        payments,
        totalHT,
        totalTVA,
        totalTTC,
        poid_balance, // ✅ 1. ON RÉCUPÈRE LE POIDS DE LA BALANCE
        urgence,
    } = props

    // Import dynamique : jsPDF (lourd) n'est chargé qu'à la génération du PDF,
    // jamais sur la page Clients (la fiche importe ce module pour les logos).
    const { default: jsPDF } = await import("jspdf")
    const doc = new jsPDF("p", "mm", "a4")
    // --- CONFIGURATION ---
    const pageWidth = doc.internal.pageSize.getWidth()
    const pageHeight = doc.internal.pageSize.getHeight()
    const margin = 15
    const contentWidth = pageWidth - margin * 2

    const colorPrimary = logo ? [30, 26, 52] : [0, 0, 0]
    const colorLightBg = [245, 245, 245]
    const colorHeaderBg = [230, 230, 230]
    const colorTextMuted = [100, 100, 100]

    // --- 1. HEADER (Logo & Vendeur) ---
    let logoData = logo ? VintageLogo : NokkProjectLogo
    if (logoData) logoData = logoData.replace(/^data:image\/\w+;base64,/, "")
    const logoW = logo ? 45 : 35
    const logoH = logo ? 35 : 35
    doc.addImage(logoData, "PNG", margin, 10, logoW, logoH)
    doc.setTextColor(0)

    if (urgence && urgence !== "normale") {
        const urgW = 65
        const urgX = pageWidth - margin - urgW
        const urgY = 15 // Aligné en haut avec le logo
        const col: [number, number, number] =
            urgence === "élevée" ? [220, 38, 38] : [234, 88, 12]

        doc.setFillColor(col[0], col[1], col[2])
        doc.roundedRect(urgX, urgY, urgW, 12, 1, 1, "F")

        doc.setTextColor(255, 255, 255)
        doc.setFont("helvetica", "bold")
        doc.setFontSize(10)
        const urgLabel =
            urgence === "élevée"
                ? "!! URGENCE ELEVEE !!"
                : "! HAUTE URGENCE !"
        doc.text(urgLabel, urgX + urgW / 2, urgY + 7.5, { align: "center" })
        doc.setTextColor(0) // Reset couleur texte
    }

    // --- 2. BANDEAU TITRE ---
    let y = 45
    doc.setFillColor(colorPrimary[0], colorPrimary[1], colorPrimary[2])
    doc.roundedRect(margin, y, contentWidth, 16, 1, 1, "F")

    doc.setTextColor(255, 255, 255)
    doc.setFont("helvetica", "bold")
    doc.setFontSize(14)
    doc.text(`BON PROFORMA N° ${numeroDevis}`, margin + 5, y + 10)

    doc.setFontSize(9)
    doc.setFont("helvetica", "normal")
    const dateText = `Émis le : ${new Date().toLocaleDateString("fr-FR")}  |  Valable jusqu'au : ${new Date(expirationDate).toLocaleDateString("fr-FR")}`
    doc.text(dateText, pageWidth - margin - 5, y + 10, { align: "right" })
    doc.setTextColor(0)

    // --- BANDE URGENCE ---
    if (urgence && urgence !== "normale") {
        const bandY = y + 17
        const col: [number, number, number] =
            urgence === "élevée" ? [220, 38, 38] : [234, 88, 12]
        doc.setFillColor(col[0], col[1], col[2])
        doc.roundedRect(margin, bandY, contentWidth, 5, 0.5, 0.5, "F")
        doc.setTextColor(255, 255, 255)
        doc.setFont("helvetica", "bold")
        doc.setFontSize(7)
        const urgLabel =
            urgence === "élevée"
                ? "!! URGENCE ELEVEE !!"
                : "! HAUTE URGENCE !"
        doc.text(urgLabel, pageWidth / 2, bandY + 3.5, { align: "center" })
        doc.setTextColor(0)
    }

    // --- 3. BLOC CLIENT & INFOS LÉGALES ---
    y += urgence && urgence !== "normale" ? 28 : 22
    const boxHeight = 32

    doc.setDrawColor(200)
    doc.roundedRect(margin, y, contentWidth, boxHeight, 1, 1, "S")

    const splitX = margin + contentWidth * 0.6
    doc.line(splitX, y, splitX, y + boxHeight)

    // --> PARTIE GAUCHE : ADRESSE
    const padX = margin + 5
    let padY = y + 6
    doc.setFont("helvetica", "bold")
    doc.setFontSize(8)
    doc.setTextColor(colorTextMuted[0], colorTextMuted[1], colorTextMuted[2])
    doc.text("DESTINATAIRE", padX, padY)

    padY += 5
    doc.setTextColor(0)
    doc.setFontSize(11)
    doc.text(
        (client.societe || client.nom || "Client Inconnu").toUpperCase(),
        padX,
        padY
    )

    padY += 5
    doc.setFont("helvetica", "normal")
    doc.setFontSize(9)
    if (client.telephone) {
        const addressLines = doc.splitTextToSize(
            client.telephone,
            contentWidth * 0.6 - 10
        )
        doc.text(addressLines, padX, padY)
    }

    padY += 5
    doc.setFont("helvetica", "normal")
    doc.setFontSize(9)
    if (client.mail) {
        const addressLines = doc.splitTextToSize(
            client.mail,
            contentWidth * 0.6 - 10
        )
        doc.text(addressLines, padX, padY)
    }

    padY += 5
    doc.setFont("helvetica", "normal")
    doc.setFontSize(9)
    if (client.localisation) {
        const addressLines = doc.splitTextToSize(
            client.localisation,
            contentWidth * 0.6 - 10
        )
        doc.text(addressLines, padX, padY)
    }

    // --> PARTIE DROITE : INFOS LÉGALES
    const legalX = splitX + 5
    padY = y + 6

    doc.setFont("helvetica", "bold")
    doc.setFontSize(8)
    doc.setTextColor(colorTextMuted[0], colorTextMuted[1], colorTextMuted[2])
    doc.text("INFORMATIONS LÉGALES", legalX, padY)

    padY += 6
    doc.setTextColor(0)
    doc.setFontSize(9)

    const drawInfoLine = (label: string, value: string) => {
        doc.setFont("helvetica", "normal")
        doc.text(label, legalX, padY)
        doc.setFont("helvetica", "bold")
        doc.text(value, legalX + 25, padY)
        padY += 5
    }

    drawInfoLine("SIRET :", clientSiret || client.siret || "—")
    drawInfoLine("TVA :", clientTva || client.numero_TVA || "—")
    if (client.nom && client.societe) {
        drawInfoLine("Contact :", client.nom)
    }

    // --- 4. TABLEAU PRODUITS ---
    y += boxHeight + 10

    const cols = {
        name: { x: margin + 2, w: 85 },
        qty: { x: margin + 90, w: 20 },
        weight: { x: margin + 110, w: 25 },
        price: { x: margin + 135, w: 25 },
        total: { x: pageWidth - margin - 2, w: 25 },
    }

    const rowHeightDefault = 9

    const drawTableHeader = (posY: number) => {
        doc.setFillColor(colorHeaderBg[0], colorHeaderBg[1], colorHeaderBg[2])
        doc.rect(margin, posY, contentWidth, 8, "F")
        doc.setFont("helvetica", "bold")
        doc.setFontSize(8)
        doc.setTextColor(50)
        doc.text("DÉSIGNATION", cols.name.x, posY + 5.5)
        doc.text("PIÈCE", cols.qty.x, posY + 5.5)
        doc.text("KILO", cols.weight.x, posY + 5.5)
        doc.text("PRIX U.", cols.price.x, posY + 5.5)
        doc.text("TOTAL HT", cols.total.x, posY + 5.5, { align: "right" })
        doc.setTextColor(0)
    }

    drawTableHeader(y)
    y += 8

    doc.setFont("helvetica", "normal")
    doc.setFontSize(10)

    products.forEach((p, index) => {
        if (y > pageHeight - 60) {
            doc.addPage()
            y = 20
            drawTableHeader(y)
            y += 8
        }

        const baseHT =
            p.totalHT !== undefined
                ? p.totalHT
                : p.mode === "Kilo"
                  ? p.price * p.weight
                  : p.price * p.qty

        const fullName = p.description ? `${p.name} - ${p.description}` : p.name
        const splitName = doc.splitTextToSize(fullName, cols.name.w)
        const rowHeight = Math.max(rowHeightDefault, splitName.length * 5 + 4)

        if (index % 2 === 1) {
            doc.setFillColor(colorLightBg[0], colorLightBg[1], colorLightBg[2])
            doc.rect(margin, y, contentWidth, rowHeight, "F")
        }

        const textY = y + rowHeight / 2 + 1.5

        doc.text(splitName, cols.name.x, y + 6)
        doc.text(p.mode === "Kilo" ? "—" : p.qty.toString(), cols.qty.x, textY)
        doc.text(
            p.weight > 0 ? `${round2(p.weight)} kg` : "—",
            cols.weight.x,
            textY
        )
        doc.text(`${round2(p.price).toFixed(2)} €`, cols.price.x, textY)
        doc.text(`${round2(baseHT).toFixed(2)} €`, cols.total.x, textY, {
            align: "right",
        })
        doc.setDrawColor(230)
        doc.line(margin, y + rowHeight, pageWidth - margin, y + rowHeight)
        y += rowHeight
    })

    // --- 5. TOTAUX ---
    y += 5
    if (y > pageHeight - 80) {
        // <-- Petite marge supp pour le poids
        doc.addPage()
        y = 20
    }

    const totalPoids = round2(
        products.reduce((sum, p) => sum + (p.weight || 0), 0)
    )

    const montantRemise =
        remise?.reduce(
            (sum, r) => sum + Math.abs(r.totalHT || r.price * (r.qty || 1)),
            0
        ) || 0

    const totalsW = 80
    const totalsX = pageWidth - margin - totalsW

    const drawTotalLine = (
        label: string,
        value: string,
        bold = false,
        color = [0, 0, 0]
    ) => {
        doc.setFont("helvetica", bold ? "bold" : "normal")
        doc.setFontSize(10)
        doc.setTextColor(color[0], color[1], color[2])
        doc.text(label, totalsX + 2, y)
        doc.text(value, pageWidth - margin - 2, y, { align: "right" })
        y += 6
        doc.setTextColor(0)
    }

    // Affichage des poids
    drawTotalLine("Poids Brut :", `${totalPoids.toFixed(2)} kg`)

    // ✅ 2. ON AFFICHE LE POIDS PESÉ (s'il est supérieur à 0)
    if (poid_balance && poid_balance > 0) {
        drawTotalLine(
            "Poids Pesé :",
            `${Number(poid_balance).toFixed(2)} kg`,
            true,
            colorPrimary // Mettre un peu en valeur avec la couleur primaire
        )
    }

    drawTotalLine("Total HT :", `${totalHT.toFixed(2)} €`, true)

    if (montantRemise > 0) {
        drawTotalLine(
            "Remise :",
            `- ${montantRemise.toFixed(2)} €`,
            false,
            [200, 0, 0]
        )
    }

    drawTotalLine("Total TVA :", `${totalTVA.toFixed(2)} €`)

    y += 3
    doc.setFillColor(colorPrimary[0], colorPrimary[1], colorPrimary[2])
    doc.roundedRect(totalsX, y - 6, totalsW, 12, 1, 1, "F")
    doc.setTextColor(255, 255, 255)
    doc.setFont("helvetica", "bold")
    doc.setFontSize(12)
    doc.text("NET À PAYER :", totalsX + 4, y + 2)
    doc.setFontSize(14)

    doc.text(`${totalTTC.toFixed(2)} €`, pageWidth - margin - 4, y + 2, {
        align: "right",
    })
    doc.setTextColor(0)

    // --- 6. INFO PAIEMENT ---
    if (payments && payments.length > 0) {
        y += 15
        doc.setFont("helvetica", "bold")
        doc.setFontSize(9)
        doc.setTextColor(
            colorTextMuted[0],
            colorTextMuted[1],
            colorTextMuted[2]
        )
        doc.text("MOYEN(S) DE RÈGLEMENT :", totalsX + 2, y)

        y += 6
        const methodString = payments.map((p) => p.method).join(" + ")
        const splitMethods = doc.splitTextToSize(methodString, totalsW - 4)
        const methodHeight = splitMethods.length * 7 + 4

        doc.setFillColor(colorLightBg[0], colorLightBg[1], colorLightBg[2])
        doc.roundedRect(totalsX, y - 5, totalsW, methodHeight, 1, 1, "F")

        doc.setTextColor(0)
        doc.setFont("helvetica", "bold")
        doc.setFontSize(11)
        doc.text(splitMethods, totalsX + 4, y)

        y += methodHeight
    }

    // --- 7. PIED DE PAGE & NOTES ---
    y = Math.max(y + 10, pageHeight - 65)
    if (y > pageHeight - 50) {
        doc.addPage()
        y = 20
    }

    const footerStart = y
    let currentY = footerStart

    // --- 1. ZONE MODE DE LIVRAISON (Checkboxes) ---
    doc.setFontSize(9)
    doc.setFont("helvetica", "bold")
    doc.text("MODE DE LIVRAISON :", margin, currentY)
    currentY += 6

    doc.setFont("helvetica", "normal")
    const boxSize = 3.5

    const livraisonVal = (Livraison || "").toLowerCase()
    const optionsLivraison = [
        {
            label: "Emporté par vos soins",
            xOffset: 0,
            isChecked:
                livraisonVal.includes("emporter") ||
                livraisonVal.includes("soins"),
        },
        {
            label: "Exworks",
            xOffset: 65,
            isChecked:
                livraisonVal.includes("exworks") ||
                livraisonVal.includes("ex works"),
        },
        {
            label: "Transport externe",
            xOffset: 110,
            isChecked: livraisonVal.includes("livraison"),
        },
    ]

    optionsLivraison.forEach((opt) => {
        const xPos = margin + opt.xOffset

        doc.setDrawColor(0)
        doc.setLineWidth(0.3)
        doc.rect(xPos, currentY - 3, boxSize, boxSize)

        if (opt.isChecked) {
            doc.setFont("helvetica", "bold")
            doc.text("X", xPos + 0.8, currentY - 0.2)
            doc.setFont("helvetica", "normal")
        }

        doc.text(opt.label, xPos + boxSize + 2, currentY)
    })

    currentY += 8

    // --- 2. ZONE NOTES ---
    doc.setFontSize(9)
    doc.setFont("helvetica", "bold")
    doc.text("NOTES & INSTRUCTIONS :", margin, currentY)

    doc.setFont("helvetica", "normal")
    doc.setFontSize(9)
    const noteText = note || "Aucune note particulière."

    const splitNotes = doc.splitTextToSize(noteText, contentWidth - 10)
    const noteBoxHeight = Math.max(15, splitNotes.length * 5 + 6)

    doc.setDrawColor(220)
    doc.roundedRect(
        margin,
        currentY + 2,
        contentWidth,
        noteBoxHeight,
        1,
        1,
        "S"
    )
    doc.text(splitNotes, margin + 2, currentY + 7)

    // --- 3. MENTION "USAGE INTERNE" & REMERCIEMENTS ---
    const bottomY = pageHeight - 15

    doc.setFontSize(9)
    doc.setFont("helvetica", "bold")
    doc.setTextColor(150, 50, 50)
    doc.text(
        "DOCUMENT RÉSERVÉ À UN USAGE INTERNE",
        pageWidth / 2,
        bottomY - 10,
        { align: "center" }
    )

    doc.setTextColor(0)
    doc.setFont("helvetica", "italic")
    doc.setFontSize(8)
    doc.text("Merci de votre confiance.", pageWidth / 2, bottomY - 5, {
        align: "center",
    })

    doc.setFont("helvetica", "normal")
    doc.setFontSize(6)
    doc.setTextColor(150)
    const editorText = `Généré par ${user?.full_name || "le système"} le ${new Date().toLocaleString()}.`
    doc.text(editorText, margin, bottomY + 5)

    const totalPages = doc.getNumberOfPages()
    for (let i = 1; i <= totalPages; i++) {
        doc.setPage(i)
        doc.setFontSize(8)
        doc.setTextColor(100)
        doc.text(
            `Page ${i}/${totalPages}`,
            pageWidth - margin,
            pageHeight - 8,
            { align: "right" }
        )
    }

    if (returnBase64) {
        const dataUri = doc.output("datauristring")
        return dataUri.split(",")[1]
    }

    const pdfUrl = doc.output("bloburl")
    window.open(pdfUrl, "_blank")
}
